sysevent_script_action.script:
(function executeAction(current, event) {

    // current IS already the OpsbridgeWorkItemStory record
    if (!current || !current.isValidRecord()) {
        gs.error('Script Action: current record is invalid');
        return;
    }

    var payload = {};
    var elements = current.getElements();

    for (var i = 0; i < elements.length; i++) {
        var fieldName = elements[i].getName();
        payload[fieldName] = current.getValue(fieldName);
    }

    payload.almKey = current.getUniqueValue();

    var r = new sn_ws.RESTMessageV2();
    r.setEndpoint(
        'https://cloudfulcrum--opsbridgqa.sandbox.my.salesforce-sites.com/services/apexrest/servicenow/workitemstory'
    );
    r.setHttpMethod('POST');
    r.setRequestHeader('Content-Type', 'application/json');
    r.setRequestBody(JSON.stringify(payload));

    var response = r.execute();
    gs.info('Salesforce response: ' + response.getStatusCode() + ' | ' + response.getBody());

})(current, event);
